%% LOAD AIRFOIL POINTS FROM FILE WITH ERROR HANDLING
function [x_points, y_points, success] = load_airfoil_points(filename)
    success = false;
    x_points = [];
    y_points = [];

    try
        % Check if file exists
        if ~exist(filename, 'file')
            error('FileNotFound', 'File "%s" does not exist.', filename);
        end

        % Try to load the file
        data = load(filename);

        % Validate data format
        if size(data, 2) < 2
            error('InvalidFormat', 'File must contain at least 2 columns (x and y coordinates).');
        end

        if size(data, 1) < 4
            error('InsufficientPoints', 'Airfoil must have at least 4 points.');
        end

        x_points = data(:, 1);
        y_points = data(:, 2);

        % Check if airfoil is closed
        if ~all(abs([x_points(1) - x_points(end), y_points(1) - y_points(end)]) < 1e-6)
            x_points = [x_points; x_points(1)];
            y_points = [y_points; y_points(1)];
            fprintf('Note: Airfoil was not closed. Added closing point.\n');
        end

        fprintf('✓ Successfully loaded %d points from %s\n', length(x_points), filename);
        success = true;

    catch ME
        fprintf('Error loading file: %s\n', ME.message);
        fprintf('Using default NACA 0012 airfoil instead.\n');
        [x_points, y_points] = create_default_airfoil();
    end
end

%% CREATE DEFAULT AIRFOIL (NACA 0012)
function [x_points, y_points] = create_default_airfoil()
    n_points = 100;
    theta = linspace(0, 2*pi, n_points);
    x_points = 0.5 * (1 + cos(theta));
    y_points = 0.12 * sin(theta);
    fprintf('Using default NACA 0012 airfoil\n');
end

%% GET FLOW CONDITIONS WITH VALIDATION
function [V_inf, alpha_deg] = get_flow_conditions()
    fprintf('\n========================================\n');
    fprintf('        FLOW CONDITIONS\n');
    fprintf('========================================\n');

    % Get free stream velocity with validation
    valid_V = false;
    while ~valid_V
        V_inf = input('Enter free stream velocity (m/s, positive number): ');

        if ~isnumeric(V_inf) || V_inf <= 0
            fprintf('Invalid input. Velocity must be a positive number.\n');
        else
            valid_V = true;
        end
    end

    % Get angle of attack with validation
    valid_alpha = false;
    while ~valid_alpha
        alpha_deg = input('Enter angle of attack (degrees, -90 to 90): ');

        if ~isnumeric(alpha_deg) || alpha_deg < -90 || alpha_deg > 90
            fprintf('Invalid input. Angle must be between -90 and 90 degrees.\n');
        else
            valid_alpha = true;
        end
    end
end

