(function() {
    'use strict';

    // Configuration
    const CONFIG = {
        TARGET_TEXT: "رزرو فقط در ساعات 9 صبح تا 10 صبح امکان پذیر است",
        RESERVATION_URL: "http://www.drtorkzadeh.com/reservation",
        TIME_RANGE: { start: { hour: 22, minute: 30 }, end: { hour: 3, minute: 30 } },
        MAIN_PAGE_PATTERNS: ['/', '/index.html', '/index.php', ''],
        CHECK_INTERVAL: 1000,
        TEXT_CHECK_DELAY: 5000
    };

    // Main Controller
    class ReservationController {
        constructor() {
            this.isFirstTab = false;
            this.isMainPage = false;
            this.init();
        }

        init() {
            // Verify first tab and main page
            this.isFirstTab = this.verifyFirstTab();
            this.isMainPage = this.verifyMainPage();

            if (!this.isFirstTab || !this.isMainPage) {
                console.log('Script not executed: Not first tab or not main page');
                return;
            }

            console.log('✅ Script initialized in first tab on main page');
            this.start();
        }

        verifyFirstTab() {
            const firstTabId = GM_getValue('firstTabId', null);
            if (!firstTabId) {
                GM_setValue('firstTabId', 'active');
                return true;
            }
            return false;
        }

        verifyMainPage() {
            const path = window.location.pathname;
            return CONFIG.MAIN_PAGE_PATTERNS.some(pattern => 
                path === pattern || path === pattern + '/'
            );
        }

        async start() {
            await this.waitForCorrectTime();
            await this.textCheckLoop();
        }

        async waitForCorrectTime() {
            while (!this.isWithinTimeRange()) {
                console.log('Outside time range (22:30-03:30). Waiting...');
                await this.delay(60000);
            }
        }

        isWithinTimeRange() {
            const now = new Date();
            const hours = now.getHours();
            const minutes = now.getMinutes();
            const currentMinutes = hours * 60 + minutes;

            const startMinutes = CONFIG.TIME_RANGE.start.hour * 60 + CONFIG.TIME_RANGE.start.minute;
            const endMinutes = CONFIG.TIME_RANGE.end.hour * 60 + CONFIG.TIME_RANGE.end.minute;

            if (hours >= 22 || hours < 3) {
                if (hours >= 22) {
                    return currentMinutes >= startMinutes;
                } else {
                    return currentMinutes <= endMinutes;
                }
            }
            return false;
        }

        async textCheckLoop() {
            while (true) {
                const hasText = await this.checkForTargetText();

                if (hasText) {
                    console.log('Target text found. Waiting 5 seconds...');
                    await this.delay(CONFIG.TEXT_CHECK_DELAY);
                    window.location.reload();
                    return;
                }

                // Text not found - switch tabs
                const success = await this.switchToReservationTab();
                if (success) return;

                await this.delay(CONFIG.CHECK_INTERVAL);
            }
        }

        async checkForTargetText() {
            const pageText = document.body.innerText || document.body.textContent;
            return pageText.includes(CONFIG.TARGET_TEXT);
        }

        async switchToReservationTab() {
            console.log('Opening reservation tab...');
            const newTab = window.open(CONFIG.RESERVATION_URL, '_blank');

            if (!newTab) {
                console.log('Failed to open new tab');
                return false;
            }

            // Mark reservation tab as ready
            GM_setValue('reservationTabReady', true);
            return true;
        }

        delay(ms) {
            return new Promise(resolve => setTimeout(resolve, ms));
        }
    }

    // Reservation Tab Handler
    class ReservationTabHandler {
        constructor() {
            this.init();
        }

        init() {
            // Only run if marked as reservation tab
            if (!GM_getValue('reservationTabReady', false)) return;

            console.log('✅ Reservation tab handler initialized');
            this.handleReservation();
        }

        async handleReservation() {
            await this.waitForPageLoad();
            await this.clickSubmitButton();
        }

        async waitForPageLoad() {
            if (document.readyState === 'complete') return;

            return new Promise(resolve => {
                window.addEventListener('load', resolve, { once: true });
                setTimeout(resolve, 5000);
            });
        }

        async clickSubmitButton() {
            // Try exact selector from instructions first
            const exactElement = document.querySelector('input[type="submit"][id="submit"]');

            if (exactElement) {
                console.log('✅ Found exact submit element');
                exactElement.click();
                return;
            }

            // Fallback to form-based search
            const forms = document.querySelectorAll('form');
            for (const form of forms) {
                const submitElement = form.querySelector('input[type="submit"], button[type="submit"]');
                if (submitElement) {
                    console.log('✅ Found form submit element');
                    submitElement.click();
                    return;
                }
            }

            console.log('❌ Could not find submit element');
        }
    }

    // Initialize appropriate handler
    function initializeScript() {
        if (GM_getValue('reservationTabReady', false)) {
            new ReservationTabHandler();
        } else {
            new ReservationController();
        }
    }

    // Start script when page loads
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initializeScript);
    } else {
        initializeScript();
    }

})();
